/**
 * 体面 · 变量结构注册 + 强制推进（代码层保证）
 *
 * 【为什么要有这个脚本】
 * 世界书里写的"每 3~4 楼推进 1 回合""第 40 回合强制触发主线"，全都要靠模型自觉。
 * 模型会忘、会偷懒、会一直写日常。
 * 所以把"保证"从提示词层下沉到代码层 —— 这里是硬约束，模型改不了。
 *
 * 【做三件事】
 * 1. 回合只许前进（模型忘了推，就强制 +1）
 * 2. 主线节点到点强制触发（写进 事件.当前事件，叙事规范要求必须先处理它）
 * 3. 自然增长（气味、察觉度）—— 不洗就是会臭，时间就是会留下痕迹
 */
import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';
import { Schema } from '../../schema';

/** 可调参数 */
const 规则 = {
  /** 每 N 回合，所有监视方察觉度自然增长 */
  察觉周期: 10,
  察觉增量: 3,
  /** 每 N 回合，气味扩散至少增长 */
  气味周期: 4,
  气味增量: 2,
  /** 每 N 回合没有任何事件时，强制派发一个微事件 */
  空转上限: 3,
  /** 主线强制节点（回合 → 事件文案） */
  主线节点: [
    { 回合: 40, 事件: '【主线·不可回避】第一次被察觉：有一个人说出"你家最近有点怪"' },
    { 回合: 120, 事件: '【主线·不可回避】父亲周立成说要回来，归期确定' },
    { 回合: 200, 事件: '【主线·不可回避】进入终局判定窗口——按【终局分支】判定' },
  ],
};

/** 微事件燃料库（空转时派发，保证永远有东西可推） */
const 微事件库 = [
  '楼道里碰见邻居，被多看了两眼',
  '她忘了锁门（她一直锁门的）',
  '妹妹提前回家',
  '对门吴敏来借东西',
  '小区停电，楼道声控灯不亮了',
  '下大雨，晾在阳台的东西全湿了',
  '快递送错到家里，收件人不是这家人',
  '她的手机响了一声，她很快按掉了',
  '灶上的锅糊了，全家都闻到',
  '表姐的记账本翻开着放在餐桌上',
  '姐夫陈默突然回来拿东西',
  '门卫老孙多问了一句"你最近回来得挺晚啊"',
  '澡洗到一半热水没了',
  '妹妹半夜起来，撞见客厅有人',
];

$(async () => {
  errorCatched(init)();
});

async function init() {
  registerMvuSchema(Schema);

  await waitGlobalInitialized('Mvu');

  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (新变量, 旧变量) => {
    // ══ 1. 回合只许前进 ══
    const 旧回合 = _.clamp(Number(_.get(旧变量, 'stat_data.回合', 1)) || 1, 1, 99999);
    let 新回合 = Number(_.get(新变量, 'stat_data.回合', 1)) || 1;

    if (新回合 <= 旧回合) {
      新回合 = 旧回合 + 1;
      _.set(新变量, 'stat_data.回合', 新回合);
      console.info(`[体面] 回合未推进 → 强制 ${旧回合} → ${新回合}`);
    }

    // ══ 2. 主线强制节点（到点就写进"当前事件"，叙事规范要求必须先处理）══
    const 已触发 = String(_.get(新变量, 'stat_data.档案.主线节点', '') || '');
    规则.主线节点.forEach(节点 => {
      if (新回合 >= 节点.回合 && 旧回合 < 节点.回合 && 已触发 !== 节点.事件) {
        _.set(新变量, 'stat_data.事件.当前事件', 节点.事件);
        _.set(新变量, 'stat_data.档案.主线节点', 节点.事件);
        console.info(`[体面] 主线节点强制触发 → ${节点.事件}`);
      }
    });

    // ══ 3. 自然增长：气味与察觉（"时间就是会留下痕迹"）══
    const 女性 = _.get(新变量, 'stat_data.女性', {});
    const 跨了气味周期 = 新回合 % 规则.气味周期 === 0 && 旧回合 % 规则.气味周期 !== 0;
    const 跨了察觉周期 = 新回合 % 规则.察觉周期 === 0 && 旧回合 % 规则.察觉周期 !== 0;

    Object.keys(女性).forEach(名字 => {
      const 路径 = `stat_data.女性.${名字}`;
      const 级别 = Number(_.get(新变量, `${路径}.级别`, 0)) || 0;

      // 气味：每 4 回合至少 +2；L4 之后（主动拒绝清洗）只涨不降
      if (跨了气味周期) {
        const 现值 = Number(_.get(新变量, `${路径}.气味扩散`, 0)) || 0;
        _.set(新变量, `${路径}.气味扩散`, _.clamp(现值 + 规则.气味增量, 0, 100));
      }

      // 察觉：每 10 回合，所有人都多知道一点（压不住的）
      if (跨了察觉周期) {
        const 现察觉 = Number(_.get(新变量, `${路径}.察觉度`, 0)) || 0;
        _.set(新变量, `${路径}.察觉度`, _.clamp(现察觉 + 规则.察觉增量, 0, 100));
      }

      // L4 之后气味不可逆（她主动拒绝清洗）
      if (级别 >= 4) {
        const 现值 = Number(_.get(新变量, `${路径}.气味扩散`, 0)) || 0;
        const 旧值 = Number(_.get(旧变量, `${路径}.气味扩散`, 0)) || 0;
        if (现值 < 旧值) {
          _.set(新变量, `${路径}.气味扩散`, 旧值);
        }
      }
    });

    // ══ 4. 空转保护：连续 N 回合没有事件 → 派发微事件（保证永远有东西推）══
    /* 注意：空转计数是**脚本内部状态**，必须放在 schema 里已声明的数值字段（事件.空转计数）。
       曾经误放在 `档案` 里——`档案` 的值类型是文本字典，写数字会导致整批变量更新校验失败。 */
    const 当前事件 = String(_.get(新变量, 'stat_data.事件.当前事件', '') || '');
    const 空转计数 = Number(_.get(新变量, 'stat_data.事件.空转计数', 0)) || 0;

    if (当前事件 && !当前事件.startsWith('【主线')) {
      // 有别的事件在处理，重置计数
      _.set(新变量, 'stat_data.事件.空转计数', 0);
    } else if (!当前事件) {
      const 新计数 = 空转计数 + 1;
      if (新计数 >= 规则.空转上限) {
        const 抽到 = 微事件库[Math.floor(Math.random() * 微事件库.length)];
        _.set(新变量, 'stat_data.事件.当前事件', `【微事件】${抽到}`);
        _.set(新变量, 'stat_data.事件.空转计数', 0);
        console.info(`[体面] 空转 ${规则.空转上限} 回合 → 派发微事件：${抽到}`);
      } else {
        _.set(新变量, 'stat_data.事件.空转计数', 新计数);
      }
    }
  });

  console.info('[体面] 变量结构已注册；强制推进钩子已挂载');
}
