/**
 * 极度色情卡 · MVU 变量结构（zod 4）
 *
 * 设计要点：
 * 1. 双轴 —— 堕落度（身体）× 变态度（认知）独立追踪，级别/象限由变量更新规则按公式重算
 * 2. 抗拒循环 —— 堕落必须锯齿状（抗拒→失守→自责→再抗拒），抗拒阶段/抗拒值/本轮抗拒理由为状态机字段
 * 3. 气味一物三用 —— 气味扩散兼作进度计、线索与证据
 * 4. 饥饿值 —— "按住不给"策略的量化，未满足度越高则欲望与变态度增长越快
 * 5. 变态六维 —— 称谓篡改 / 日常殖民 / 审美反转 / 仪式化 / 人格崩解 / 共同体扩张
 * 6. 方言随堕落级变浓 —— 方言浓度由级别推导，是失控的听觉指标
 *
 * ★ 容错铁律（依 tavern-card-builder/references/schema.md §2 与 pitfalls.md #9/#17/#18）：
 *   1. 每个字段都必须带 `.catch(默认值)`——**校验失败要转化生效，不许整体丢弃**
 *      （只有 .prefault 是不够的：它只处理 undefined，AI 写错类型/枚举会让整批 parse fail
 *         → 表现就是"发生变量更新错误，可能需要重roll"，且连累同一批里所有正常字段）
 *   2. 数值一律 `z.coerce.number()` + `transform(clamp)`，不用 .min/.max
 *   3. 枚举一律带 `.catch()`——AI 写近义值（"抗拒" vs "抗拒中"）是最常见的 fail 源
 *   4. 自由文本字典一律用 `z.unknown().transform(手工拍平)`——**不许用 union+partial 接嵌套**（会静默吞数据）
 *   5. 布尔不 coerce（coerce 会把字符串 "false" 转成 true）
 *   6. 所有 transform 必须幂等（`parse(parse(x)) === parse(x)`）
 */
/* ══════════════════════════════════════════════════════════════
   工具构造器：把"容错"写进类型本身，避免逐个字段漏掉 .catch()
   ══════════════════════════════════════════════════════════════ */
/** 数值：类型错/越界 → 转化生效（clamp），彻底坏掉 → 默认值 */
const num = (lo, hi, d) => z
    .coerce.number()
    .transform(v => _.clamp(Number.isFinite(v) ? v : d, lo, hi))
    .prefault(d)
    .catch(d);
/** 整数：同上，先取整 */
const int = (lo, hi, d) => z
    .coerce.number()
    .transform(v => _.clamp(Math.round(Number.isFinite(v) ? v : d), lo, hi))
    .prefault(d)
    .catch(d);
/** 字符串：任何非字符串 → 默认值（不报错） */
const str = (d = '') => z.string().prefault(d).catch(d);
/** 布尔：不 coerce（"false" 会被 coerce 成 true） */
const bool = (d = false) => z.boolean().prefault(d).catch(d);
/** 枚举：AI 写近义值/写错字 → 落回默认值，不炸整批 */
const pick = (vals, d) => z.enum(vals).prefault(d).catch(d);
/**
 * 自由文本条目：AI 可能写"一段话"，也可能写结构化对象（键名还不固定）
 * → 一律手工拍平成文本存库（严禁 union+partial 接嵌套：那会静默吞数据）
 * 幂等：文本进 → 同样文本出
 */
const 拍平 = (v) => {
    if (v == null)
        return '';
    if (typeof v === 'string')
        return v;
    if (typeof v === 'number' || typeof v === 'boolean')
        return String(v);
    if (Array.isArray(v))
        return v.map(拍平).filter(Boolean).join('；');
    if (typeof v === 'object') {
        return Object.entries(v)
            .map(([k, val]) => `${k}：${拍平(val)}`)
            .join('｜');
    }
    return String(v);
};
const 文本条 = z.unknown().transform(拍平).catch('');
/**
 * 自由文本字典：值可以是任意形态，统一拍平。
 *
 * ★ 为什么不用 `z.record(...)`：字典的 key 常是**轮次（数字）**，而 MVU 应用 JSON Patch
 *   落库时若走 lodash.set，`/档案/2` 在容器为空时会**建成数组** `[null, {...}]`
 *   （`_.set({}, 'a.1', v)` → `{a:[null,v]}`），`z.record` 拒绝数组 → 整本字典被 catch 成 {}，
 *   数据**静默丢失**。所以这里用 `z.unknown().transform` 同时接受对象与数组两种形态。
 */
const 文本记录 = z
    .unknown()
    .transform(v => {
    const out = {};
    if (Array.isArray(v)) {
        v.forEach((x, i) => {
            if (x != null)
                out[String(i)] = 拍平(x);
        });
    }
    else if (v !== null && typeof v === 'object') {
        for (const [k, val] of Object.entries(v))
            out[k] = 拍平(val);
    }
    return out;
})
    .prefault({})
    .catch({});
/** 布尔字典：任意写法归一到布尔，同样兼容数组形态 */
const 布尔条 = z
    .unknown()
    .transform(v => {
    if (typeof v === 'boolean')
        return v;
    if (typeof v === 'number')
        return v !== 0;
    const s = String(v ?? '').trim().toLowerCase();
    return s === 'true' || s === '1' || s === '是' || s === 'yes' || s === '已触发';
})
    .catch(false);
const 布尔记录 = z
    .unknown()
    .transform(v => {
    const out = {};
    if (Array.isArray(v)) {
        v.forEach((x, i) => {
            if (x != null)
                out[String(i)] = 布尔条.parse(x);
        });
    }
    else if (v !== null && typeof v === 'object') {
        for (const [k, val] of Object.entries(v))
            out[k] = 布尔条.parse(val);
    }
    return out;
})
    .prefault({})
    .catch({});
